1	// gcec local check: package.json's hand-kept test:offline list must stay in sync
2	// with the extension-test/ mirror tree — it names every extension-test/**/*.test.js
3	// that exists, and only files that exist. `npm test` discovers by glob, so a test
4	// missing from test:offline still runs there; what this check catches is the
5	// offline suite silently thinning as tests are added, moved, or renamed (the rule
6	// this converts was prose in the project's old testing procedure doc).
7	//
8	// Local-pack check modules are dependency-free on purpose: they return plain
9	// finding objects ({ rule, severity, file, line, what, why, fix, doc }) instead of
10	// importing the engine's checks/lib helpers — the mount those helpers live in is
11	// gitignored and absent on a fresh checkout, and this module must also load under
12	// the repo's own `npm test` (pack.test.mjs).
13	const id = 'test-offline-list-sync';
14	const severity = 'blocking';
15	const doc = '.claudinite/local/packs/gcec/RULES.md';
16	const why =
17	  'npm test discovers by glob but test:offline is a hand-kept list — a new or ' +
18	  'moved extension-test file silently drops out of the offline suite';
19	
20	const isMirrorTest = (p) => p.startsWith('extension-test/') && p.endsWith('.test.js');
21	
22	export default {
23	  id,
24	  severity,
25	  description: 'package.json test:offline lists exactly the extension-test unit tests',
26	  doc,
27	  why,
28	
29	  run(ctx) {
30	    const raw = ctx.read('package.json');
31	    if (!raw) return [];
32	    let script;
33	    try {
34	      script = JSON.parse(raw).scripts?.['test:offline'];
35	    } catch {
36	      return []; // malformed package.json breaks npm first — not this check's finding
37	    }
38	    if (typeof script !== 'string') return [];
39	
40	    const listed = script.split(/\s+/).filter(isMirrorTest);
41	    const findings = [];
42	    // Direction 1 — a mirror-tree test the list is missing. ctx.files is the whole
43	    // repo under the engine's default `all` sweep (check-the-world); under a
44	    // --changed run it narrows to changed files, which only ever under-reports.
45	    for (const file of ctx.files.filter(isMirrorTest)) {
46	      if (!listed.includes(file)) {
47	        findings.push({
48	          rule: id, severity, file: 'package.json', line: null,
49	          what: `test:offline is missing ${file}`,
50	          why,
51	          fix: `add ${file} to the test:offline list in package.json`,
52	          doc,
53	        });
54	      }
55	    }
56	    // Direction 2 — a listed file that doesn't exist (moved/renamed away). Probed
57	    // via ctx.exists, not ctx.files, so a --changed run can't false-positive.
58	    for (const file of listed) {
59	      if (!ctx.exists(file)) {
60	        findings.push({
61	          rule: id, severity, file: 'package.json', line: null,
62	          what: `test:offline lists ${file}, which does not exist`,
63	          why,
64	          fix: `remove ${file} from the test:offline list or fix its path`,
65	          doc,
66	        });
67	      }
68	    }
69	    return findings;
70	  },
71	};
