// Regression test for issue #48: the pipeline files must not clobber each
// other's contributions to globalThis.GCal regardless of the order they run in.
// registry.js creates GCal.sources, the helpers add the shared toolbox, and the
// sources push their { name, matches, extract } onto GCal.sources; because every
// file augments GCal with Object.assign (rather than replacing it), loading them
// in any order keeps every contribution intact.
"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");

const ROOT = path.join(__dirname, "..", "..");
const EXT = path.join(ROOT, "extension"); // the extension root; pipeline paths are relative to it

function runInFreshSandbox(files) {
  const sandbox = { document: undefined, URL };
  vm.createContext(sandbox);
  for (const file of files) {
    vm.runInContext(fs.readFileSync(path.join(EXT, file), "utf8"), sandbox);
  }
  return sandbox;
}

test("a helper loaded before the registry still leaves both intact", () => {
  // Deliberately load a helper before registry.js (the reverse of the load order).
  const sandbox = runInFreshSandbox(["event-extractors/helpers/dom.js", "event-extractors/registry.js"]);

  // registry.js must not have wiped out the helper's contribution...
  assert.equal(typeof sandbox.GCal.clean, "function", "the dom helper survives");
  // ...nor should the helper have prevented registry.js's bootstrap.
  assert.ok(Array.isArray(sandbox.GCal.sources), "GCal.sources is present");
});

test("a source registers onto GCal.sources whichever order the base files run", () => {
  for (const baseOrder of [
    ["event-extractors/registry.js", "event-extractors/helpers/dom.js"],
    ["event-extractors/helpers/dom.js", "event-extractors/registry.js"],

// Guards event-extractors/load-order.generated.json against drift: it must match what
// `npm run index` (gen-load-order.js) would produce from the current extractor
// files. If this fails, an extractor was added/removed/renamed without
// regenerating the list — run `npm run index` and commit the result.

"use strict";

const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { computeLoadOrder, render, OUTPUT } = require("../gen-load-order");

const ROOT = path.join(__dirname, "..", "..", "..");
// OUTPUT is relative to the extension root (extension/), where the generated
// load list is committed alongside the pipeline it lists.
const EXT = path.join(ROOT, "extension");

test("the committed load order matches `npm run index`", () => {
  const committed = fs.readFileSync(path.join(EXT, OUTPUT), "utf8");
  assert.equal(
    committed,
    render(computeLoadOrder()),
    "extension/event-extractors/load-order.generated.json is stale — run `npm run index` and commit it"
  );
});

test("the registry loads first and the orchestrator loads last", () => {
  const list = computeLoadOrder();
  assert.equal(list[0], "event-extractors/registry.js", "the registry must load first");
  // After the registry, the helpers form a contiguous block before any
  // extract layer or source.
  const afterRegistry = list.slice(1);
  const firstNonHelper = afterRegistry.findIndex((f) => !f.startsWith("event-extractors/helpers/"));
  assert.ok(
    afterRegistry.slice(firstNonHelper).every((f) => !f.startsWith("event-extractors/helpers/")),
    "the helpers must load before the extract layers and sources"
  );
  assert.equal(
    list[list.length - 1],
    "event-extractors/assemble-events.js",
    "the orchestrator (assemble-events.js) must load last"
  );
});
