  .split('\n')
  .filter(Boolean)
  .filter((f) => !f.startsWith('.claudinite/shared/')); // the engine drops the vendored canon

const ctx = {
  files,
  allFiles: files,
  read: (p) => {
    try {
      return fs.readFileSync(`${ROOT}/${p}`, 'utf8');
    } catch {
      return null;
    }
  },
  exists: (p) => fs.existsSync(`${ROOT}/${p}`),
};

let total = 0;
for (const rule of pack.worldRules) {
  const findings = rule.run(ctx);
  total += findings.length;
  console.log(`${rule.id}: ${findings.length} finding(s)`);
  for (const f of findings) console.log(`   - ${f.file}: ${f.what}`);
}
console.log(total === 0 ? '\nALL GREEN on the real repo' : `\n${total} finding(s)`);

